insert into public.facilities (
  rin, phmsa_name, phmsa_address, city, state, postal_code,
  source_effective_date, source_row_count, candidate_type_hint,
  pipeline_status, publish_status, commercial_status, identity_confidence
)
select
  rin, phmsa_name, phmsa_address, city, state, postal_code,
  source_effective_date, source_row_count, candidate_type_hint,
  'needs_enrichment', 'review', 'unknown', 0
from data
on conflict (rin) do update set
  phmsa_name = excluded.phmsa_name,
  phmsa_address = excluded.phmsa_address,
  city = excluded.city,
  state = excluded.state,
  postal_code = excluded.postal_code,
  source_effective_date = excluded.source_effective_date,
  source_row_count = excluded.source_row_count,
  candidate_type_hint = excluded.candidate_type_hint;

insert into public.source_records (
  facility_id, source, raw_payload, hydrostatic_authorized, effective_date
)
select
  f.id,
  'PHMSA Approved Cylinder Re-testers',
  jsonb_build_object(
    'rin', f.rin,
    'phmsa_name', f.phmsa_name,
    'phmsa_address', f.phmsa_address,
    'city', f.city,
    'state', f.state,
    'postal_code', f.postal_code,
    'source_effective_date', f.source_effective_date,
    'source_row_count', f.source_row_count,
    'candidate_type_hint', f.candidate_type_hint,
    'hydrostatic_flag', 'Y'
  ),
  true,
  f.source_effective_date
from public.facilities f
where not exists (
  select 1 from public.source_records s
  where s.facility_id = f.id
    and s.source = 'PHMSA Approved Cylinder Re-testers'
);
